/**
 * FR-D4 — the global print pipeline.
 *
 * This is the **only** component in the application that renders a printable
 * page. Report cards, class lists, permits, registers and every future export
 * go through `<Sheet>`, which stamps the institution's name and logo into the
 * header and "Generated by Results Manager" plus the page number and print date
 * into the footer.
 *
 * There is no prop for a sponsor name or third-party attribution, and no way to
 * suppress the header or the footer — FR-D4 says no requirement may bypass this
 * pipeline, so the component gives no bypass to use.
 */

import type { ReactNode } from "react";
import { Printer } from "lucide-react";

import type {
  Branding,
  ClassListBody,
  DocumentEnvelope,
  Footer,
  ReportCard,
  ReportCardBatch,
} from "../lib/types";
import { Button } from "./ui";

// ---------------------------------------------------------------------------
// The sheet
// ---------------------------------------------------------------------------

interface SheetProps {
  branding: Branding;
  footer: Footer;
  title: string;
  subtitle?: ReactNode;
  landscape?: boolean;
  pageNumber: number;
  pageCount: number;
  children: ReactNode;
}

function Sheet({
  branding,
  footer,
  title,
  subtitle,
  landscape = false,
  pageNumber,
  pageCount,
  children,
}: SheetProps) {
  const contact = [branding.address, branding.phone, branding.email]
    .filter(Boolean)
    .join("  •  ");

  return (
    <article className={landscape ? "sheet sheet-landscape" : "sheet"}>
      {/* --- Institution branding. Never anything else. --- */}
      <header className="doc-head">
        {branding.logoDataUrl ? (
          <img className="doc-logo" src={branding.logoDataUrl} alt="" />
        ) : (
          <div className="doc-logo-placeholder">No logo</div>
        )}

        <div className="doc-identity">
          <div className="doc-institution">{branding.institutionName}</div>
          {branding.motto && <div className="doc-motto">“{branding.motto}”</div>}
          {contact && <div className="doc-contact">{contact}</div>}
        </div>

        {/* Balances the logo so the name stays optically centred. */}
        <div className="doc-logo-placeholder" style={{ visibility: "hidden" }} />
      </header>

      <div className="doc-title">{title}</div>
      {subtitle && <div className="doc-subtitle">{subtitle}</div>}

      <div className="doc-body">{children}</div>

      {/* --- Fixed footer, per FR-D4. --- */}
      <footer className="doc-foot">
        <span>{footer.generatedBy}</span>
        <span>
          Page {pageNumber} of {pageCount}
        </span>
        <span>Printed {footer.printedOn}</span>
      </footer>
    </article>
  );
}

// ---------------------------------------------------------------------------
// Preview frame (screen only — hidden at print time)
// ---------------------------------------------------------------------------

export function PrintPreview({
  actions,
  children,
}: {
  actions?: ReactNode;
  children: ReactNode;
}) {
  return (
    <div className="print-root">
      <div className="print-toolbar no-print">
        <Button
          variant="primary"
          icon={<Printer size={15} />}
          onClick={() => window.print()}
        >
          Print
        </Button>
        {actions}
      </div>
      {children}
    </div>
  );
}

// ---------------------------------------------------------------------------
// FR-D1 — report card
// ---------------------------------------------------------------------------

export function ReportCardSheets({
  envelope,
}: {
  envelope: DocumentEnvelope<ReportCardBatch>;
}) {
  const { branding, footer, body } = envelope;
  const total = body.cards.length;

  return (
    <>
      {body.cards.map((card, index) => (
        <ReportCardSheet
          key={card.studentId}
          branding={branding}
          footer={footer}
          batch={body}
          card={card}
          pageNumber={index + 1}
          pageCount={total}
        />
      ))}
    </>
  );
}

function ReportCardSheet({
  branding,
  footer,
  batch,
  card,
  pageNumber,
  pageCount,
}: {
  branding: Branding;
  footer: Footer;
  batch: ReportCardBatch;
  card: ReportCard;
  pageNumber: number;
  pageCount: number;
}) {
  const title = batch.isFinal
    ? "End of Term Report Card"
    : "Progress Report Card";

  const attendance =
    card.daysPresent !== null && card.daysPossible !== null && card.daysPossible > 0
      ? `${card.daysPresent} of ${card.daysPossible} days`
      : "—";

  return (
    <Sheet
      branding={branding}
      footer={footer}
      title={title}
      subtitle={`${batch.termName}  •  ${batch.academicYear}`}
      pageNumber={pageNumber}
      pageCount={pageCount}
    >
      <div className="rc-learner">
        {card.photoDataUrl && (
          <img className="rc-photo" src={card.photoDataUrl} alt="" />
        )}
        <div className="rc-fields">
          <Field label="Name" value={card.fullName} />
          <Field label="Reg. No." value={card.regNumber} />
          <Field
            label="Class"
            value={
              card.streamName ? `${card.className} — ${card.streamName}` : card.className
            }
          />
          <Field label="Sex" value={card.gender === "M" ? "Male" : card.gender === "F" ? "Female" : "—"} />
          <Field label="Term" value={batch.termName} />
          <Field label="Days present" value={attendance} />
        </div>
      </div>

      <table className="rc-table">
        <thead>
          <tr>
            <th className="left" style={{ width: "34%" }}>
              Subject
            </th>
            {batch.examNames.map((name) => (
              <th key={name}>{name}</th>
            ))}
            <th>Term</th>
            <th>Out of</th>
            <th>Grade</th>
            <th className="left" style={{ width: "18%" }}>
              Remark
            </th>
          </tr>
        </thead>
        <tbody>
          {card.subjects.map((subject) => (
            <tr key={subject.classSubjectId} className={subject.isCore ? "" : "non-core"}>
              <td className="subject">{subject.name}</td>
              {subject.examScores.map((score, index) => (
                <td key={index}>{score === null ? "—" : round(score)}</td>
              ))}
              <td>{subject.termScore === null ? "—" : round(subject.termScore)}</td>
              <td>{subject.maxScore}</td>
              <td className="grade">{subject.gradeLabel}</td>
              <td className="left">{subject.remark ?? ""}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className="rc-summary">
        {card.totalPoints !== null && (
          <div className="rc-summary-box">
            <div className="rc-summary-label">Aggregate</div>
            <div className="rc-summary-value">{round(card.totalPoints)}</div>
          </div>
        )}
        {card.division && (
          <div className="rc-summary-box">
            <div className="rc-summary-label">Division</div>
            <div className="rc-summary-value">{card.division}</div>
          </div>
        )}
        <div className="rc-summary-box">
          <div className="rc-summary-label">Average</div>
          <div className="rc-summary-value">
            {card.meanPercentage === null ? "—" : `${round(card.meanPercentage)}%`}
          </div>
        </div>
        <div className="rc-summary-box">
          <div className="rc-summary-label">Position</div>
          <div className="rc-summary-value">
            {card.position === null ? "—" : `${card.position} / ${card.classSize}`}
          </div>
        </div>
      </div>

      <div className="rc-comments">
        <div className="rc-comment">
          <div className="rc-comment-label">Class Teacher's comment</div>
          <div className="rc-comment-text">{card.classTeacherComment ?? ""}</div>
        </div>
        <div className="rc-comment">
          <div className="rc-comment-label">Headteacher's comment</div>
          <div className="rc-comment-text">{card.headTeacherComment ?? ""}</div>
        </div>
      </div>

      <div className="rc-signature">Headteacher's signature &amp; school stamp</div>
    </Sheet>
  );
}

function Field({ label, value }: { label: string; value: string }) {
  return (
    <div className="rc-field">
      <span className="rc-field-label">{label}</span>
      <span className="rc-field-value">{value}</span>
    </div>
  );
}

// ---------------------------------------------------------------------------
// FR-D2 — class list
// ---------------------------------------------------------------------------

export function ClassListSheet({
  envelope,
}: {
  envelope: DocumentEnvelope<ClassListBody>;
}) {
  const { branding, footer, body } = envelope;

  return (
    <Sheet
      branding={branding}
      footer={footer}
      title="Class List"
      subtitle={
        body.termName
          ? `${body.className}  •  ${body.termName}  •  ${body.academicYear}`
          : `${body.className}  •  ${body.academicYear}`
      }
      pageNumber={1}
      pageCount={1}
    >
      <table className="cl-table">
        <thead>
          <tr>
            <th className="num">#</th>
            <th style={{ width: "22%" }}>Reg. No.</th>
            <th>Name</th>
            <th style={{ width: "8%" }}>Sex</th>
            <th style={{ width: "22%" }}>Guardian</th>
            <th style={{ width: "18%" }}>Phone</th>
          </tr>
        </thead>
        <tbody>
          {body.rows.map((row) => (
            <tr key={row.regNumber}>
              <td className="num">{row.number}</td>
              <td>{row.regNumber}</td>
              <td>{row.fullName}</td>
              <td>{row.gender ?? "—"}</td>
              <td>{row.guardianName ?? "—"}</td>
              <td>{row.guardianPhone ?? "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className="cl-totals">
        <span>Total: {body.total}</span>
        <span>Boys: {body.boys}</span>
        <span>Girls: {body.girls}</span>
      </div>
    </Sheet>
  );
}

function round(value: number): string {
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}
